    [1539]={name="Gnarled Hermit's Staff",quality=2,ilvl=21,reqLevel=16,sourceType="rare_npc",instructions="Drops from Geopriest Gukk'rok.",zone="The Barrens",npc="Geopriest Gukk'rok"},
    [1547]={name="Shield of the Faith",quality=2,ilvl=30,reqLevel=23,sourceType="quest_reward",instructions="Reward from the quest 'Worgen in the Woods'. Pick it over the other reward choices. Starts with Calor in Duskwood. Objective: Bring Calor's note to Jonathan Carevin.",zone="Duskwood",questName="Worgen in the Woods",lore="Here you go. Bring this message to Master Carevin. A few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today."},
    [1557]={name="Buckler of the Seas",quality=2,ilvl=20,reqLevel=15,sourceType="quest_reward",instructions="Reward from the quest 'The Coastal Menace'. Pick it over the other reward choices. Starts with Captain Grayson in Westfall. Objective: Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.",zone="Westfall",questName="The Coastal Menace",lore="When my life was ended upon the rocks, I had no clue what the afterlife held for me. The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off."},
    [1561]={name="Harvester's Robe",quality=2,ilvl=15,reqLevel=8,sourceType="quest_reward",instructions="Reward from the quest 'The Killing Fields'. Pick it over the other reward choices. Starts with Farmer Saldean in Westfall. Objective: Farmer Saldean wants you to kill 20 Harvest Watchers.",zone="Westfall",questName="The Killing Fields",lore="Look at what has happened to this place! These lands were once occupied by good farm folk. But the damned thieves have driven them all off. Not me, though!"},
