    [1893]={name="Miner's Revenge",quality=2,ilvl=20,reqLevel=15,sourceType="quest_reward",instructions="Reward from the quest 'Oh Brother. . .'. Starts with Wilder Thistlenettle in Stormwind City. Objective: Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.",zone="The Deadmines",questName="Oh Brother. . .",lore="We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us."},
