    [10358]={name="Duracin Bracers",quality=3,ilvl=38,reqLevel=30,sourceType="quest_reward",instructions="Reward from the quest 'Power Stones'. Pick it over the other reward choices. Starts with Rigglefuzz in Badlands. Objective: Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.",zone="Uldaman",questName="Power Stones",lore="A while ago, I had an incident with the Shadowforge Dwarves. They brought me to Angor Fortress to study two types of strange stones from Uldaman."},
    [10359]={name="Everlast Boots",quality=2,ilvl=38,reqLevel=30,sourceType="quest_reward",instructions="Reward from the quest 'Power Stones'. Pick it over the other reward choices. Starts with Rigglefuzz in Badlands. Objective: Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.",zone="Uldaman",questName="Power Stones",lore="A while ago, I had an incident with the Shadowforge Dwarves. They brought me to Angor Fortress to study two types of strange stones from Uldaman."},
    [10405]={name="Bandit Shoulders",quality=1,ilvl=22,reqLevel=17,sourceType="world_drop",instructions="World drop around level 17-22.",zone="The Barrens",zoneOpen=true},
