    [12022]={name="Iridium Chain",quality=2,ilvl=41,reqLevel=36,sourceType="world_drop",instructions="World drop around level 36-42.",zone="Stranglethorn Vale"},
    [12026]={name="Quicksilver Pendant",quality=2,ilvl=59,reqLevel=54,sourceType="world_drop",instructions="World drop around level 38-61.",zone="Eastern Plaguelands"},
