    [15587]={name="Ringtail Girdle",quality=2,ilvl=35,reqLevel=31,sourceType="quest_reward",instructions="Reward from the quest 'Clam Bait'. Pick it over the other reward choices. Starts with Mai'Lahii in Desolace. Objective: Find 10 pieces of Soft-shelled Clam Meat and bring it back to Mai'Lahii at Shadowprey Village.",zone="Desolace",questName="Clam Bait",lore="You have the look of a fisherman! I love to fish - been fishing all my life. The best bait to use is soft-shelled clam meat; the fish just can't resist, you know what I mean?"},
